import{_ as a,C as t,o as n,c as l,j as s,a as o,E as i,a2 as d}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Modules","description":"","frontmatter":{"title":"Modules"},"headers":[],"relativePath":"guide/modules.md","filePath":"guide/modules.md"}'),u={name:"guide/modules.md"};function c(g,e,p,m,f,v){const r=t("Capture");return n(),l("div",null,[e[0]||(e[0]=s("h1",{id:"modules",tabindex:"-1"},[o("Modules "),s("a",{class:"header-anchor",href:"#modules","aria-label":'Permalink to "Modules"'},"​")],-1)),e[1]||(e[1]=s("p",null,[o("Cet écran montre chaque module de votre projet — chaque stack déclarée dans "),s("code",null,"effortless.json"),o(" — sur une carte. Vous y venez pour savoir, d'un coup d'œil, où en est chaque partie du code : sa version, son dépôt, sa livraison et le travail qui l'a touchée.")],-1)),i(r,{name:"modules",alt:"L'écran Modules : une carte par module, avec son identité, son git et sa version, sa livraison et son travail"}),e[2]||(e[2]=d('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>En haut, le nombre de modules déclarés. Puis une carte par module, avec son nom, son chemin et des pastilles : <strong>dépôt propre</strong> (le module a son propre dépôt git) ou <strong>dépôt racine</strong> (il vit dans celui du projet), <strong>livrable</strong> s&#39;il a une livraison déclarée, <strong>dossier absent</strong> si son chemin n&#39;existe pas.</p><p>Chaque carte a cinq blocs :</p><ul><li><strong>Identité</strong> : les <strong>Langages</strong>, le <strong>Modèle</strong> de stack et les <strong>Normes</strong> présentes pour ce module.</li><li><strong>Git et version</strong> : la <strong>Version</strong> lue dans ses fichiers (<code>package.json</code>, sinon <code>Cargo.toml</code>), la <strong>Branche</strong>, le nombre de <strong>Fichiers modifiés</strong>, le <strong>Dernier tag</strong> et le <strong>Dernier commit</strong>.</li><li><strong>Livraison</strong> : la commande de <strong>Build</strong> et les <strong>Artefacts</strong> déclarés dans l&#39;écran Livraison. Sinon : « Aucune livraison déclarée pour ce module. »</li><li><strong>Travail (90 jours)</strong> : le nombre de <strong>Commits</strong> qui ont touché le module, les <strong>Épics · stories · tâches</strong> qu&#39;ils citent, et les <strong>Épics récents</strong>.</li><li><strong>Builds</strong> : le <strong>Volume de build</strong> du module à la dernière mesure, avec sa date (« Jamais mesuré » sinon), le détail par dossier de build, et le <strong>Débogage du module</strong> et <strong>des dépendances</strong>. Le volume s&#39;affiche en couleur quand il dépasse le seuil du projet (10 Go par défaut, réglable par <code>settings.build_volume.threshold</code> dans <code>effortless.json</code>).</li></ul><p>Si une source n&#39;a pas pu être lue — par exemple un dossier qui n&#39;est pas un dépôt git —, la carte le dit : « Une source n&#39;a pas pu être lue », avec le détail au survol. Si git ne dit rien du module, le bloc Travail affiche « Rien de lisible dans git pour ce module. » Rien n&#39;est caché.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><p>Le bloc <strong>Builds</strong> agit sur les dossiers de build du module — ce que la compilation produit et qui se régénère :</p><ul><li><strong>Mesurer</strong> parcourt les dossiers de build : ceux que déclare la stack et ceux que l&#39;outil de build a marqués comme cache. La mesure compte l&#39;occupation réelle du disque, chaque fichier une seule fois. Elle reste propre à votre poste.</li><li><strong>Nettoyer…</strong> affiche d&#39;abord ce qui se passera : la commande de remise à zéro déclarée par le langage (par exemple <code>cargo clean</code>), et la taille qui sera libérée. Rien ne part avant que vous cliquiez sur <strong>Nettoyer</strong>. La compilation suivante sera complète.</li><li>Les sélecteurs de <strong>débogage</strong> règlent la quantité d&#39;informations de débogage des builds de dev : <strong>aucun</strong>, <strong>lignes seules</strong> ou <strong>complet</strong>. Le réglage s&#39;applique aux commandes qu&#39;Effortless lance pour ce module, sans réécrire aucun de vos fichiers. Une portée que le langage ne sait pas régler affiche « non réglable » : pour Rust, c&#39;est le cas des dépendances, qui restent sans débogage.</li></ul><p>Quand un module dépasse le seuil, l&#39;écran de reprise du <a href="/Effortless/guide/dashboard.html">Tableau de bord</a> affiche « Builds lourds » et mène ici.</p><p>Le reste de l&#39;écran se lit sans rien écrire. Un module se déclare par l&#39;étape <strong>Stack</strong> de l&#39;<a href="/Effortless/guide/create.html">Assistant de création</a>, par <strong>Préférences</strong> › <strong>Modèle de stack</strong> (<strong>Créer la stack</strong>), ou par un agent avec <code>effortless_stack_add</code>. Sa livraison se règle dans l&#39;écran <a href="/Effortless/guide/release.html">Livraison</a>.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Un agent lit la même chose par le verbe <code>effortless_modules</code>. Le bloc Builds a ses verbes : <code>effortless_build_volume</code> (mesurer), <code>effortless_build_reset</code> (nettoyer, simulation d&#39;abord) et <code>effortless_build_debug</code> (débogage) — voir <a href="/Effortless/agent/code.html">Code et stacks</a>.</p>',12))])}const q=a(u,[["render",c]]);export{b as __pageData,q as default};
